<?php
// Dar 3.33.44 — read-only look after the install: the prices a checkout is made of, the trial days of each plan, and the state of the last checkouts (no names, no e-mails)
$R = '/home/u791571885/domains/dar.ink/public_html'; chdir($R); require $R . '/dar-sync.php'; require_once $R . '/dar-pay.php'; require_once $R . '/dar-whop.php'; @require_once $R . '/dar-trials.php';
$o = ['v' => SYNC_VERSION, 'now' => gmdate('c'), 'renew_price' => bill_cfg()['renew_price'] ?? null];
foreach (bill_platform_rows('plans') as $p) if (in_array($p->audience ?? '', ['office', 'builder'], true)) $o['trial'][] = [$p->audience, $p->code, function_exists('trial_plan_days') ? trial_plan_days((string)$p->audience, (string)$p->code, 'month') : null, $p->trial_days_month ?? null, $p->trial_days ?? null];
foreach ([['builder', 'b_starter', 'SA'], ['builder', 'b_starter', 'DE'], ['office', 'basic', 'JP']] as [$a, $pl, $cc]) { $T = (object)['id' => 'probe', 'audience' => $a, 'country' => $cc, 'plan' => $pl, 'status' => 'active'];
  try { $q = pay_quote($T, $pl, 'month', '', []); $o['q'][] = [$cc, $q['currency'], $q['rate'], $q['plan_price'], $q['total'], pay_terms($q), $q['renew_mode'] ?? '']; } catch (Throwable $e) { $o['q'][] = [$cc, $e->getMessage()]; } }
try { pay_db(); foreach (q("SELECT id, ns, kind, status, data, at FROM pay_txns WHERE data LIKE '%whop%' ORDER BY at DESC LIMIT 6")->fetchAll() as $x) { $d = json_decode((string)$x['data'], true) ?: []; $T = bill_tenant((string)$x['ns']);
  $o['txns'][] = ['kind' => $x['kind'], 'st' => $x['status'], 'at' => gmdate('c', (int)($x['at'] / 1000)), 'quote' => $d['quote'] ?? null, 'cur' => $d['currency'] ?? null, 'trial_kept' => $d['trial_days'] ?? ($d['trial'] ?? null),
    't' => $T ? ['aud' => $T->audience ?? '', 'plan' => $T->plan ?? '', 'cc' => $T->country ?? '', 'status' => $T->status ?? '', 'why' => $T->suspend_reason ?? '', 'checkout_first' => $T->checkout_first ?? null, 'trial_end' => $T->trial_end ?? '', 'signup_cycle' => $T->signup_cycle ?? '', 'trial_now' => pay_trial_days($T, 'month', (string)($T->plan ?? ''))] : null]; } } catch (Throwable $e) { $o['txns_err'] = $e->getMessage(); }
echo json_encode($o, JSON_UNESCAPED_UNICODE);
